<?php
namespace App\Controllers\Auth;use App\Support\App;
final class AuthController{public function login():never{$in=App::input();$q=App::db()->prepare('SELECT * FROM users WHERE email=? AND status="active"');$q->execute([trim($in['email']??'')]);$u=$q->fetch();if(!$u||!password_verify($in['password']??'',$u['password']))App::json(['ok'=>false,'message'=>'Email/password salah'],422);$_SESSION['uid']=$u['id'];App::json(['ok'=>true,'redirect'=>$u['role']==='admin'?'/admin':'/dashboard']);}public function register():never{$in=App::input();if(App::setting('registration_enabled','1')!=='1')App::json(['ok'=>false,'message'=>'Pendaftaran ditutup'],403);$name=trim($in['name']??'');$email=trim($in['email']??'');$pass=$in['password']??'';if(!$name||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pass)<8)App::json(['ok'=>false,'message'=>'Data tidak valid'],422);$lvl=App::db()->query("SELECT id FROM user_levels WHERE code='user'")->fetchColumn();try{App::db()->prepare('INSERT INTO users(name,email,password,level_id) VALUES(?,?,?,?)')->execute([$name,$email,password_hash($pass,PASSWORD_DEFAULT),$lvl]);App::json(['ok'=>true]);}catch(\Throwable $e){App::json(['ok'=>false,'message'=>'Email sudah digunakan'],409);}}}
